import * as T from './vendor/three.module.js';
import {tile,clock} from './horizons.js';
export function worldLighting(r){const faces=[];for(let side=0;side<6;side++){const c=document.createElement('canvas');c.width=c.height=32;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,0,32);g.addColorStop(0,side===3?'#6b7056':'#b5cfda');g.addColorStop(.6,'#d9dbbf');g.addColorStop(1,side===2?'#c9d7d9':'#5a6952');x.fillStyle=g;x.fillRect(0,0,32,32);faces.push(c);}const cube=new T.CubeTexture(faces);cube.colorSpace=T.SRGBColorSpace;cube.needsUpdate=true;const pmrem=new T.PMREMGenerator(r.gl);r.environment=pmrem.fromCubemap(cube);r.scene.environment=r.environment.texture;r.scene.environmentIntensity=.35;cube.dispose();pmrem.dispose();r.rim=new T.DirectionalLight('#b9d9e1',.5);r.rim.position.set(8,15,-12);r.scene.add(r.rim);r.lamps=[];for(let i=0;i<4;i++){const light=new T.PointLight('#ffb85d',0,4,2);r.scene.add(light);r.lamps.push(light);}r.shoreUniform={value:new T.DataTexture(new Uint8Array([0,0,0,255]),1,1)};r.shoreUniform.value.needsUpdate=true;r.shoreBounds={value:new T.Vector4(0,0,1,1)};r.M.water.userData.shore=r.shoreUniform;r.M.water.userData.bounds=r.shoreBounds;}
export function animateLighting(r,state){const night=clock(state).night;r.skyLight.intensity=night?.3:1.05;r.scene.environmentIntensity=night?.12:.35;r.M.lantern.emissiveIntensity=night?3.2:.15;r.M.window.emissiveIntensity=night?.9:.06;r.rim.intensity=night?.25:.5;const buildings=night&&!r.layer?r.map.buildings.filter(b=>b.hp>0&&b.progress>=1&&['camp','house','barracks','market','dock'].includes(b.type)&&r.onScreen(b.x,b.y,60)).sort((a,b)=>Math.hypot(a.x-r.focus.x,a.y-r.focus.y)-Math.hypot(b.x-r.focus.x,b.y-r.focus.y)).slice(0,4):[];r.lamps.forEach((light,i)=>{const b=buildings[i];light.intensity=b?2.2:0;if(b)light.position.set(b.x+1-r.origin,tile(r.map,b.x,b.y).h*.3+.65,b.y+1.5-r.origin);});}
export function updateShore(r,bounds){const m=r.map,w=bounds.x1-bounds.x0+1,h=bounds.y1-bounds.y0+1,data=new Uint8Array(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const xx=bounds.x0+x,yy=bounds.y0+y,i=(y*w+x)*4;let depth=1;if(m.fog[yy*m.size+xx]&&tile(m,xx,yy).kind==='water'){for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1],[2,0],[-2,0],[0,2],[0,-2]])if(xx+dx>=0&&xx+dx<m.size&&yy+dy>=0&&yy+dy<m.size&&m.fog[(yy+dy)*m.size+xx+dx]&&tile(m,xx+dx,yy+dy).kind!=='water')depth=Math.min(depth,Math.abs(dx+dy)*.28);}data.set([depth*255,0,0,255],i);}const old=r.shoreUniform.value;if(old.image.width===w&&old.image.height===h){old.image.data=data;old.needsUpdate=true;}else{old.dispose();r.shoreUniform.value=new T.DataTexture(data,w,h);r.shoreUniform.value.magFilter=T.LinearFilter;r.shoreUniform.value.minFilter=T.LinearFilter;r.shoreUniform.value.needsUpdate=true;}r.shoreBounds.value.set(bounds.x0-r.origin,bounds.y0-r.origin,w,h);}
